CREATE TYPE "InsuranceQuestionSchemaStatus" AS ENUM ('DRAFT','PUBLISHED','RETIRED');
CREATE TYPE "InsuranceQuestionFieldType" AS ENUM ('TEXT','TEXTAREA','NUMBER','DATE','BOOLEAN','SINGLE_SELECT','MULTI_SELECT','CURRENCY','PHONE','EMAIL');
CREATE TYPE "InsuranceDataClassification" AS ENUM ('GENERAL','CONTACT','FINANCIAL_PREFERENCE','HEALTH_SENSITIVE','VEHICLE','IDENTITY');
CREATE TYPE "InsuranceVisibilityOperator" AS ENUM ('EQUALS','NOT_EQUALS','IN','NOT_IN','IS_TRUE','IS_FALSE');
CREATE TYPE "InsuranceNeedAssessmentStatus" AS ENUM ('DRAFT','IN_PROGRESS','READY_FOR_REVIEW','SUBMITTED','EXPIRED','WITHDRAWN');
CREATE TYPE "InsuranceConsentStatus" AS ENUM ('GRANTED','WITHDRAWN');

CREATE TABLE "InsuranceQuestionSchema" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "policyTypeId" UUID NOT NULL, "name" TEXT NOT NULL, "version" INTEGER NOT NULL, "status" "InsuranceQuestionSchemaStatus" NOT NULL DEFAULT 'DRAFT', "effectiveFrom" TIMESTAMP(3), "effectiveUntil" TIMESTAMP(3), "createdByAdminUserId" UUID NOT NULL, "publishedByAdminUserId" UUID, "publishedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "InsuranceQuestionSchema_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InsuranceQuestionSection" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "questionSchemaId" UUID NOT NULL, "key" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT, "sortOrder" INTEGER NOT NULL DEFAULT 0, "isRequired" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "InsuranceQuestionSection_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InsuranceQuestion" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "sectionId" UUID NOT NULL, "key" TEXT NOT NULL, "label" TEXT NOT NULL, "description" TEXT, "helpText" TEXT, "fieldType" "InsuranceQuestionFieldType" NOT NULL, "dataClassification" "InsuranceDataClassification" NOT NULL DEFAULT 'GENERAL', "isRequired" BOOLEAN NOT NULL DEFAULT false, "sortOrder" INTEGER NOT NULL DEFAULT 0, "validationConfig" JSONB NOT NULL DEFAULT '{}', "visibilityConfig" JSONB NOT NULL DEFAULT '{}', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "InsuranceQuestion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InsuranceQuestionOption" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "questionId" UUID NOT NULL, "value" TEXT NOT NULL, "label" TEXT NOT NULL, "description" TEXT, "sortOrder" INTEGER NOT NULL DEFAULT 0, "isActive" BOOLEAN NOT NULL DEFAULT true, CONSTRAINT "InsuranceQuestionOption_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InsuranceNeedAssessment" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "referenceNumber" TEXT NOT NULL, "userId" UUID NOT NULL, "policyTypeId" UUID NOT NULL, "questionSchemaVersionId" UUID NOT NULL, "status" "InsuranceNeedAssessmentStatus" NOT NULL DEFAULT 'DRAFT', "currentSectionKey" TEXT, "completionPercentage" INTEGER NOT NULL DEFAULT 0, "version" INTEGER NOT NULL DEFAULT 1, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastSavedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "submittedAt" TIMESTAMP(3), "expiredAt" TIMESTAMP(3), "withdrawnAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "InsuranceNeedAssessment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InsuranceNeedAnswer" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "assessmentId" UUID NOT NULL, "questionId" UUID NOT NULL, "valueJson" JSONB NOT NULL, "encryptedValue" TEXT, "dataClassification" "InsuranceDataClassification" NOT NULL, "createdByUserId" UUID NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "InsuranceNeedAnswer_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InsuranceDisclosureAcknowledgement" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "userId" UUID NOT NULL, "assessmentId" UUID NOT NULL, "disclosureTemplateId" UUID NOT NULL, "disclosureVersion" INTEGER NOT NULL, "acknowledgedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "context" JSONB NOT NULL DEFAULT '{}', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "InsuranceDisclosureAcknowledgement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InsuranceConsentRecord" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "userId" UUID NOT NULL, "assessmentId" UUID NOT NULL, "consentTemplateId" UUID NOT NULL, "consentVersion" INTEGER NOT NULL, "purpose" "InsuranceConsentPurpose" NOT NULL, "status" "InsuranceConsentStatus" NOT NULL DEFAULT 'GRANTED', "grantedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "withdrawnAt" TIMESTAMP(3), "source" TEXT NOT NULL DEFAULT 'WEB', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "InsuranceConsentRecord_pkey" PRIMARY KEY ("id"));
CREATE TABLE "InsuranceNeedProfileSnapshot" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "assessmentId" UUID NOT NULL, "schemaVersion" INTEGER NOT NULL, "policyTypeId" UUID NOT NULL, "answersSnapshot" JSONB NOT NULL, "disclosureSnapshot" JSONB NOT NULL, "consentSnapshot" JSONB NOT NULL, "submittedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "InsuranceNeedProfileSnapshot_pkey" PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "InsuranceQuestionSchema_policyTypeId_version_key" ON "InsuranceQuestionSchema"("policyTypeId","version");
CREATE UNIQUE INDEX "InsuranceQuestionSection_questionSchemaId_key_key" ON "InsuranceQuestionSection"("questionSchemaId","key");
CREATE UNIQUE INDEX "InsuranceQuestion_sectionId_key_key" ON "InsuranceQuestion"("sectionId","key");
CREATE UNIQUE INDEX "InsuranceQuestionOption_questionId_value_key" ON "InsuranceQuestionOption"("questionId","value");
CREATE UNIQUE INDEX "InsuranceNeedAssessment_referenceNumber_key" ON "InsuranceNeedAssessment"("referenceNumber");
CREATE UNIQUE INDEX "InsuranceNeedAnswer_assessmentId_questionId_key" ON "InsuranceNeedAnswer"("assessmentId","questionId");
CREATE UNIQUE INDEX "InsuranceDisclosureAcknowledgement_assessmentId_disclosureTemplateId_key" ON "InsuranceDisclosureAcknowledgement"("assessmentId","disclosureTemplateId");
CREATE UNIQUE INDEX "InsuranceConsentRecord_assessmentId_consentTemplateId_key" ON "InsuranceConsentRecord"("assessmentId","consentTemplateId");
CREATE UNIQUE INDEX "InsuranceNeedProfileSnapshot_assessmentId_key" ON "InsuranceNeedProfileSnapshot"("assessmentId");
CREATE INDEX "InsuranceNeedAssessment_userId_status_updatedAt_idx" ON "InsuranceNeedAssessment"("userId","status","updatedAt");
CREATE INDEX "InsuranceQuestionSchema_policyTypeId_status_effectiveFrom_effectiveUntil_idx" ON "InsuranceQuestionSchema"("policyTypeId","status","effectiveFrom","effectiveUntil");

